package com.google.gson.stream;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class JsonWriter_value_TriageGen0Test {













    @Test
    public void testValue_FluentInterface() throws IOException {
        StringWriter out = new StringWriter();
        JsonWriter writer = new JsonWriter(out);
        writer.beginArray();
        JsonWriter returnedWriter = writer.value(1.0);
        writer.endArray();

        assertEquals(writer, returnedWriter);
        assertEquals("[1.0]", out.toString());
    }
}
